render:
const { root, params, progress, time, width, height } = ctx;
const canvas = root.querySelector('#hacker-canvas');
if (!canvas) return;

if (canvas.width !== width || canvas.height !== height) {
  canvas.width = width;
  canvas.height = height;
}

const c = canvas.getContext('2d');
const text = params.title || "ACCESS GRANTED";
const fontFamily = params.font_family || "Consolas";
const mainFontSize = params.main_font_size || 60;
const cipherSpeed = params.cipher_speed || 18;
const greenColor = params.matrix_color || "#00FF66";
const bgColor = params.background_color || "#050B05";
const glowBlur = params.glow_intensity || 20;
const charSetType = params.char_set || "Katakana + Simbolos";
const showRain = params.bg_rain;
const showScanlines = params.scanlines;
const rainFontSize = params.rain_font_size || 14;
const rainSpeed = params.rain_speed || 1;
const rainColStep = Math.max(1, Math.round(params.rain_column_step || 2));
const rainTrail = Math.max(1, Math.round(params.rain_trail_length || 8));
const scanOpacity = params.scanline_opacity;
const flickerIntensity = params.flicker_intensity;

const sets = {
  "Katakana + Simbolos": "ウアウエオカキケコサシスセソタツテナニヌネハヒホマミムメモヤユラリワ1234567890#$%&*+=-",
  "Binario (01)": "0101010101",
  "Hexadecimal": "0123456789ABCDEF",
  "ASCII Hacker": "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789@#$%&*<>/|{}[]"
};
const charset = sets[charSetType] || sets["Katakana + Simbolos"];

c.fillStyle = bgColor;
c.fillRect(0, 0, width, height);

const cx = width / 2;
const cy = height / 2;

if (showRain) {
  c.save();
  c.font = `${rainFontSize}px ${fontFamily}, monospace`;
  const cols = Math.floor(width / rainFontSize);
  c.fillStyle = greenColor;

  for (let col = 0; col < cols; col += rainColStep) {
    const seed = col * 33.7;
    const speed = (80 + (seed % 100)) * rainSpeed;
    const colY = (time * speed + seed * 20) % (height + 200) - 100;
    const colX = col * rainFontSize;

    for (let j = 0; j < rainTrail; j++) {
      const charIdx = Math.floor((time * 10 + col + j * 7) % charset.length);
      const randomChar = charset[charIdx];
      const alpha = (1 - (j / rainTrail));
      c.globalAlpha = alpha * 0.3;
      c.fillText(randomChar, colX, colY - j * rainFontSize);
    }
  }
  c.restore();
}

c.save();
c.font = `bold ${mainFontSize}px "${fontFamily}", monospace`;
c.textAlign = "center";
c.textBaseline = "middle";

const textLength = text.length;
const revealCount = Math.floor(Math.min(1, progress / 0.85) * textLength);

let displayedText = "";
for (let i = 0; i < textLength; i++) {
  if (i < revealCount) {
    displayedText += text[i];
  } else {
    const pseudoSeed = Math.floor(time * cipherSpeed + i * 11);
    const charIndex = pseudoSeed % charset.length;
    displayedText += charset[charIndex];
  }
}

c.shadowColor = greenColor;
c.shadowBlur = glowBlur;

c.fillStyle = greenColor;
c.fillText(displayedText, cx, cy);

c.restore();

if (showScanlines) {
  c.save();
  c.fillStyle = `rgba(0, 0, 0, ${scanOpacity})`;
  for (let y = 0; y < height; y += 4) {
    c.fillRect(0, y, width, 2);
  }
  const flicker = flickerIntensity * Math.sin(time * 50);
  c.fillStyle = `rgba(0, 255, 100, ${Math.max(0, flicker)})`;
  c.fillRect(0, 0, width, height);
  c.restore();
}
